// ora-sfc-fin — generated from src/ora-sfc-fin-*.js by tools/merge.js. Edit the src files, then run: node tools/merge.js
// Oracle Senior Functional Consultant (3–5 yrs) — Finance. Format: [module, question, answer, 'B' basic | 'D' in-depth]
QB["ora-sfc-fin"] = (QB["ora-sfc-fin"] || []).concat([
["Implementation", "Walk me through the phases of an Oracle Cloud implementation and your role in each.", "**Why they ask:** senior consultants need to know the life cycle and their part in it.\n\n**Answer:**\n\"Most projects follow Oracle Unified Method or a client's agile hybrid. Discovery and planning gathers requirements, current processes and scope. Design, or CRP1, configures a baseline, demos it to the business and runs fit-gap. Build, or CRP2, finishes configuration and builds extensions, reports, integrations and conversions. Testing covers SIT, UAT and parallel runs or reconciliations. Deploy covers mock conversions, cutover, go-live and hypercare. As a senior consultant I own the module design, for example AP and Payments: I write the functional design, configure, write test scripts, lead the CRP demos, train key users, and support cutover and hypercare.\"\n\nTip: Name what you own in each phase. That's the real question.", "B", null, null, {"t":1,"f":["Which phase do projects most often underinvest in?","Testing, especially end-to-end and data validation. Projects that rush testing find their issues at the first month-end close."]}],
["Implementation", "What is a Conference Room Pilot (CRP) and how do you run a good one?", "**Why they ask:** CRPs are where design is won or lost.\n\n**Answer:**\n\"A CRP is a scripted demo of the configured system using the client's own data and processes, so the business can validate the design. I agree scenarios in advance, like 'PO-matched invoice with a price variance'. I use realistic data: their suppliers, accounts and amounts. I walk end to end, including accounting and reports, not just screens. I capture gaps and decisions live in a log with owners. And I follow up with updated designs and a sign-off. CRP1 validates the baseline; CRP2 validates the near-final solution with integrations.\"\n\nTip: Mention using the client's real data. It's what makes the business engage.", "B", null, null, {"f":["What do you do if users reject the design in a CRP?","Capture the objection, find out whether it's a real requirement or habit, and agree a decision with the process owner within days so the build isn't delayed."]}],
["Implementation", "How do you handle a requirement that Oracle cannot meet out of the box?", "**Why they ask:** customization decisions affect cost and upgrades for years.\n\n**Answer:**\n\"First I challenge the requirement: is it a real business need or a legacy habit? Could a process change solve it? Then I look for configuration: descriptive flexfields, SLA rules, approval rules, BIP reports or OTBI. If that's not enough, I look for a light extension: a Visual Builder page, an OIC integration, a BIP report, or a REST-based process. I record it in the RICEW inventory with its cost and support impact. And the business signs off on the trade-off.\"\n\nTip: Give an example where you avoided an extension by changing the process. Interviewers love that.", "B", null, null, {"t":1,"f":["When would you accept a custom extension?","When the requirement is legal or business-critical, configuration can't meet it, and the client accepts the maintenance cost through quarterly updates."]}],
["Subledger Accounting", "How would you change the liability account on AP invoices based on supplier type using SLA?", "**Why they ask:** a hands-on SLA question. They want the exact steps.\n\n**Answer:**\n\"In Manage Accounting Methods I copy the seeded Standard Accrual method; I never edit seeded. I create a mapping set with supplier type as input and natural account value as output. Then I create an account derivation rule for the liability that starts from the default account and overrides the natural account segment with the mapping set result. I copy the seeded journal entry rule set for the Invoices event class and attach the new rule to the Liability journal line. I activate the rule set and assign the new method to the ledger. Then I test invoice, payment, cancellation and prepayment application.\"\n\nTip: Keep the steps in order. It's a test of whether you've actually clicked through it.", "D", null, null, {"t":1,"f":["How would you test that rule change?","Run draft Create Accounting for invoices from each supplier type and confirm the liability account, before moving the method to production."]}],
["Subledger Accounting", "What are mapping sets, sources and supporting references in SLA?", "**Why they ask:** these three are the building blocks of SLA rules.\n\n**Answer:**\n\"Sources are the transaction data SLA can use in rules, like supplier type, item category or project; custom sources can be built from attributes and descriptive flexfields. Mapping sets are lookup tables that turn an input value into a segment value or a full account, for example item category to natural account. Supporting references are extra attributes stored on journal lines, like supplier or invoice number, so you can report balances by them and reconcile. I find supporting references most useful for intercompany and tax account reconciliations.\"\n\nTip: Give one use for each. It keeps the answer practical.", "D", null, null, {"t":1,"f":["Give an example where supporting references solved a reporting problem.","Tracking AP liability balances by supplier on a shared account, so the team could reconcile by supplier without separate accounts."]}],
["General Ledger", "How do you configure journal approval in Fusion GL?", "**Why they ask:** journal approval is a key financial control.\n\n**Answer:**\n\"I enable journal approval on the ledger and on the journal sources that need it, like Manual and Spreadsheet. The rules are set in BPM through Manage Journal Approval Rules: by journal amount, for example over $50,000 goes to the controller; by ledger or category; and by supervisor hierarchy or approval groups. I test the edge cases: amounts exactly at the threshold, journals across ledgers, and self-approval prevention. Subledger journals usually don't need approval, because they're controlled upstream.\"\n\nTip: Mention testing at the threshold amount. It's the case that usually breaks.", "D", null, null, {"f":["How would you route journals over $250,000 to the CFO?","A BPM rule on journal amount routing to an approval group containing the CFO, after the controller approves."]}],
["General Ledger", "What is AutoPost and when would you use it?", "**Why they ask:** AutoPost keeps GL current without manual effort.\n\n**Answer:**\n\"AutoPost automatically posts journals that match criteria sets, by ledger, source, category, period and priority. I use it for subledger journals from Payables, Receivables and Assets, and for trusted integrations, so finance doesn't post them by hand. It runs on a schedule. I leave out sources that need review, like manual journals. Combined with Create Accounting's transfer and post options, GL stays current every day.\"\n\nTip: Say which sources you'd exclude. That's the control part of the answer.", "D", null, null, {"f":["Why not AutoPost manual journals?","They should go through review and approval; AutoPost suits trusted system sources like subledgers."]}],
["General Ledger", "How do segment value security rules work?", "**Why they ask:** security design affects users and performance.\n\n**Answer:**\n\"Segment value security limits which values of a segment a user can see or use, for example a regional accountant can only use cost centers in their region. I enable security on the value set, create data security policies with the value conditions, and grant them through roles in the Security Console. It applies to entry, inquiry and reporting, and works alongside data access sets, which control ledger and balancing segment access. I'm careful with it, because too many rules slow things down and confuse users.\"\n\nTip: Mention the performance cost. It shows you've seen it go wrong.", "D", null, null, {"f":["What happens if you enable segment value security without granting any values?","Users can't see or use any value of that segment, which effectively blocks them. Grants must be in place before enabling."]}],
["General Ledger", "What is a data access set?", "**Why they ask:** a basic GL security question.\n\n**Answer:**\n\"A data access set controls which ledgers or ledger sets, and which primary balancing segment values, a user can access in GL, and whether it's read-only or read and write. It can give full ledger access or only specific values, like companies 101 to 110. It's assigned to users with their GL roles through Manage Data Access for Users. With a ledger set, one data access set can cover many ledgers that share a chart and calendar.\"\n\nTip: Give the example of a company range. It makes the answer concrete.", "B", null, null, {"f":["How is a data access set different from a role?","The role says what you can do; the data access set says which ledgers and balancing values you can do it in."]}],
["Intercompany", "How does Fusion Intercompany work?", "**Why they ask:** intercompany is complex, and Fusion has two parts that people confuse.\n\n**Answer:**\n\"There are two parts. Intercompany balancing is automatic: when a journal crosses balancing values, GL or SLA creates due-to and due-from lines based on the intercompany balancing rules. Intercompany transactions use the Intercompany module: one entity creates a transaction, like a management fee, the partner approves it, and it creates journals in both ledgers and, if needed, AR and AP invoices to settle it. The setup includes intercompany organizations, transaction types, receivables and payables assignments, and the intercompany reconciliation report.\"\n\nTip: Separate the two parts clearly. It's what the question is testing.", "D", null, null, {"t":1,"f":["When would you use intercompany transactions instead of balancing?","When entities charge each other with formal invoices, needing both sides approved and possibly AR and AP documents."]}],
["Intercompany", "How do you reconcile intercompany balances at month end?", "**Why they ask:** intercompany differences delay consolidation.\n\n**Answer:**\n\"I run the Intercompany Reconciliation report, which compares due-to and due-from between each pair of entities. Then I investigate the differences: timing, where one side booked in the next period; FX rate differences; missing transactions; and manual journals with the wrong intercompany segment. Having an intercompany segment in the chart makes it possible to report balances by trading partner. I agree a cut-off date and a settlement process, usually netting. Eliminations happen in consolidation, in FCCS or with GL elimination rules.\"\n\nTip: List the causes in order of how often you see them. Timing is usually first.", "D", null, null, {"t":1,"f":["What's the most common source of intercompany differences?","Timing, where one side records in this period and the other next period, and FX rate differences."]}],
["Accounts Payable", "How do you configure invoice approval workflow in Fusion Payables?", "**Why they ask:** a hands-on configuration question for senior functional consultants.\n\n**Answer:**\n\"I turn on invoice approval in Manage Invoice Options for the business unit, then build the rules in BPM through Manage Invoice Approval Rules. A typical set: PO-matched invoices within tolerance need no approval, non-PO invoices go to the cost center manager by amount, and anything over $100,000 adds the controller. I use approval groups or the supervisor hierarchy, with a fallback for missing approvers. I decide whether approval happens before or after validation, and whether payment requires approval. Then I test the real-life paths: reassign, delegate, request information and reject.\"\n\n1. Enable invoice approval (Manage Invoice Options).\n2. Build rules in BPM (Manage Invoice Approval Rules).\n3. Approval groups or hierarchy, with a fallback.\n4. Set approval order and payment requirement.\n5. Test reassign, delegate, request info, reject.\n\nTip: Mentioning the test scenarios shows you've been through UAT, not just setup.", "D", null, null, {"t":1,"f":["How do you handle approvals when a cost center manager leaves?","Route by position or approval group rather than named person, and keep HCM data current."]}],
["Accounts Payable", "What is Intelligent Document Recognition (IDR) / invoice imaging?", "**Why they ask:** most companies want to stop keying invoices. They want to know you can set up Oracle's capture.\n\n**Answer:**\n\"IDR is Oracle's AI-based invoice capture. Suppliers email PDF or image invoices to a dedicated address. IDR reads the invoice and creates an incomplete invoice with the header and lines filled in, matched to the PO where it can find one. AP reviews and completes the exceptions in the Invoices work area. It gets more accurate as it learns supplier layouts. On a rollout I watch three things: supplier communication about where to send invoices, duplicate detection for invoices that arrive by email and by mail, and the touchless rate and processing time.\"\n\nTip: Bring up duplicates. Invoices arriving by two routes is the most common IDR problem after go-live.", "D", null, null, {"f":["What touchless rate can IDR reach?","It varies by supplier and invoice quality; well-formatted PO invoices from regular suppliers often go through with little correction after training."]}],
["Payments", "How do you set up a new payment format, for example a bank's ACH file?", "**Why they ask:** bank integration is where projects often slip. They want to know you can handle it end to end.\n\n**Answer:**\n\"First I get the bank's file specification and their test process. Then I take a seeded BI Publisher template, like NACHA or ISO 20022 pain.001, copy it and adjust it to the bank's requirements. I create the payment format pointing to that template, and a payment process profile that links the format, the payment method, the transmission over SFTP or web service, and the grouping rules. The profile is assigned to the disbursement bank account and payment methods. Then testing with the bank: prenotes, a few small live payments, and making sure we receive and process the acknowledgment files.\"\n\n1. Bank specification and test plan.\n2. Copy and adjust the seeded template.\n3. Payment format.\n4. Payment process profile.\n5. Assign to bank account and methods.\n6. Test: prenotes, small live payments, acknowledgments.\n\nTip: Mention acknowledgment files. Teams forget them, then can't tell whether the bank accepted the payments.", "D", null, null, {"t":1,"f":["What's your test process with the bank?","Send test files in the bank's test environment, fix rejections, then do a small live penny test before full rollout."]}],
["Payments", "What is positive pay?", "**Why they ask:** a common treasury control, and they want to know you've set it up, not just heard of it.\n\n**Answer:**\n\"Positive pay is a fraud control for checks. After each check run, we send the bank a file of the checks we issued: number, amount and payee. The bank only pays checks that match, and anything that doesn't match becomes an exception for treasury to approve or reject. In Fusion, I run the Positive Pay File process with a BI Publisher template in the bank's format, include voided checks so they can't be cashed, and transmit it automatically over SFTP after each payment run.\"\n\nTip: Mention voided checks in the file. It shows you understand why the control exists.", "B", null, null, {"f":["What does positive pay not protect against?","Electronic payment fraud like ACH changes; it only covers checks, so bank account change controls matter too."]}],
["Payments", "How do you void a payment and what happens to the invoices and accounting?", "**Why they ask:** voids have side effects on invoices, accounting, 1099 and the bank. They want to see you think about all of them.\n\n**Answer:**\n\"I void the payment in Payables with a void date and choose what happens to the invoices: cancel them, put them on hold, or leave them open to pay again. The accounting reverses the payment on the void date. If the payment already cleared the bank, I can't just void it, it becomes a stop payment or a refund. For electronic payments, I only void if the bank actually rejected the payment. And I check the knock-on effects: 1099 amounts and the next positive pay file, which should include the void.\"\n\n**Example:** a $3,000 check is voided and the invoice left open.\n- Entry: Dr Cash Clearing 3,000 / Cr AP Liability 3,000\n- The invoice is unpaid again and picked up by the next payment run.\n\nTip: Covering the 1099 and positive pay impact is what lifts this answer above average.", "D", null, null, {"f":["What happens to the accounting when a payment is voided?","The cash or clearing entry and liability relief are reversed in the void date's period."]}],
["Accounts Receivable", "How do you set up Lockbox processing?", "**Why they ask:** lockbox is the main high-volume cash channel in the US. They want the steps.\n\n**Answer:**\n\"I define the lockbox with the bank's transmission format, usually BAI2 or a custom format the bank provides, and map the file fields to Oracle fields. Then I set the matching rules: match on transaction number, PO number, sales order or consolidated bill number. AutoCash rules handle receipts where nothing matches. The process runs import, validate, then post QuickCash and apply. In Fusion that's one program, Process Receipts Through Lockbox. The KPI I'd track is the percentage of lockbox receipts applied automatically. Getting that from 60% to 85% usually takes better customer references, not more setup.\"\n\nTip: Name the format and the KPI. It shows you've worked with a bank file, not just the setup screen.", "D", null, null, {"f":["What do you check when lockbox receipts don't apply?","Matching rules and the references in the file, like invoice numbers or customer numbers, and the AutoMatch thresholds."]}],
["Accounts Receivable", "How does Fusion Revenue Management support ASC 606 / IFRS 15?", "**Why they ask:** revenue is a high-risk area. They want to know you understand the accounting as well as the module.\n\n**Answer:**\n\"Revenue Management follows the five steps of ASC 606. Source documents, like sales orders, contracts and AR invoices, come in and are grouped into customer contracts, which is step one. The lines become performance obligations, step two. The transaction price, step three, is allocated across the obligations by relative standalone selling price, which finance sets by item or item class, step four. Revenue is then recognized when each obligation is satisfied, step five, either at a point in time, like shipment or acceptance, or over time, like ratably over a support period. The accounting gives contract assets, contract liabilities for deferred revenue, and revenue. It also handles contract changes and discounts.\"\n\nTip: Walk through the five steps and say which part of the module does each. That's the best answer they'll hear.", "D", null, null, {"t":1,"f":["What is the hardest part of Revenue Management setup?","Standalone selling prices and identifying performance obligations correctly, since allocation depends on them."]}],
["Accounts Receivable", "How does credit management work in Fusion?", "**Why they ask:** credit links AR to sales. They want the flow from limit to hold release.\n\n**Answer:**\n\"Customers get credit profiles with a limit and a review cycle. When an order is booked in Order Management, a credit check compares exposure, which is open receivables plus uninvoiced orders, to the limit. If it's over, the order goes on credit hold. Analysts then work a credit review in a case folder, which pulls in aging, payment history and external scores like D&B. They recommend releasing the hold or changing the limit, and the change routes for approval. Once approved, the hold is released and the order moves on.\"\n\nTip: Describe the path order → check → hold → review → release. It's what they're listening for.", "D", null, null, {"f":["What makes up credit exposure?","Open receivables plus uninvoiced orders, sometimes including orders on hold, compared to the limit."]}],
["Fixed Assets", "How do you handle construction-in-progress (CIP) assets?", "**Why they ask:** CIP sits on the balance sheet and is easy to forget.\n\n**Answer:**\n\"Costs are collected as CIP assets, either from AP mass additions or from Projects. CIP doesn't depreciate. When construction is finished, I capitalize the CIP asset: it gets a date placed in service and starts depreciating. With Fusion Projects, capital projects build the assets, generate asset lines and interface them to Assets. The control I always set up is a CIP aging review every month, so a building that's been in use for six months doesn't sit in CIP with no depreciation.\"\n\nTip: The CIP aging review is the key control. Say it.", "D", null, null, {"t":1,"f":["What happens if CIP isn't capitalized when the asset is in use?","Depreciation starts late, understating expense, and auditors will flag it."]}],
["Fixed Assets", "How do you merge or split mass additions?", "**Why they ask:** a practical Assets task that shows you've done the work.\n\n**Answer:**\n\"Merge combines several invoice lines into one asset, for example adding the freight and installation lines to the main equipment line. Split turns one line into many assets, like a line for 10 laptops becoming 10 separate assets. Add to Asset puts the cost onto an asset that's already in service. I do all of this in the Mass Additions work area before posting. Merged lines take the parent line's category and details, so I make sure the parent is set up correctly first.\"\n\nTip: Give the laptop and freight examples. They cover both actions.", "B", null, null, {"f":["When would you split a mass addition?","When one invoice line covers several assets, like 10 laptops, that need separate tracking."]}],
["Cash Management", "How do you design reconciliation rule sets for high auto-match rates?", "**Why they ask:** a hands-on design question with a measurable result.\n\n**Answer:**\n\"I start by reading real bank statements to see which references each bank actually returns: check number, payment reference, invoice number. Then I build rules from strict to loose: exact reference and amount first, then amount with a date tolerance, then one-to-many and many-to-one for batches. I add tolerance rules for small differences like fees, and transaction creation rules for recurring charges. Then I make sure our outgoing payment files carry a reference the bank sends back, like the ISO 20022 end-to-end ID. After go-live I measure the auto-match rate monthly and adjust. Going from 70% to above 90% is normal with that approach.\"\n\nTip: Start with \"I read the statements first\". It shows you design from data.", "D", null, null, {"t":1,"f":["What auto-match rate do you aim for?","Over 90%, then I review unmatched patterns monthly to add rules."]}],
["Tax", "How would you set up a new tax rate, for example a VAT rate change in a country?", "**Why they ask:** rate changes happen every year somewhere, and mistakes mean wrong tax on invoices.\n\n**Answer:**\n\"In Manage Tax Rates I end-date the current rate and create the new one from the effective date, or add a new rate period under the same rate code. I check whether tax rules need changing, and check the recovery rates and accounts. Then I test AP, AR and PO transactions dated before and after the change. I tell the AP and AR teams what's changing, and check the reports and the tax filing for the switch-over period. The tricky cases are transactions that span the date, like an invoice dated before the change but credited after it.\"\n\nTip: Mention transactions that span the date. It's the case that catches people out.", "D", null, null, {"f":["What do you test after a rate change?","Transactions dated before and after the effective date to confirm each picks the right rate."]}],
["Budgetary Control", "What is budgetary control and encumbrance accounting?", "**Why they ask:** important in public sector, higher education and some corporates.\n\n**Answer:**\n\"Budgetary control checks spending against budgets in real time. Requisitions, POs and invoices are stopped if they go over the available funds with absolute control, or just warned with advisory control. Encumbrance reserves the funds as spending moves along: a requisition encumbrance, then a PO encumbrance, then the actual on the invoice, with each step relieving the one before. Setup includes control budgets, budgetary control rules, control levels by segment, and loading the budgets. A funds check only validates; a funds reserve actually uses up the funds.\"\n\nTip: Explain funds check vs funds reserve. It's the detail that proves hands-on work.", "D", null, null, {"f":["What's the difference between absolute and advisory control?","Absolute blocks transactions over budget; advisory warns but allows."]}]
]);

QB["ora-sfc-fin"] = (QB["ora-sfc-fin"] || []).concat([
["Reporting", "How would you build a financial statement in Fusion?", "**Why they ask:** financial statements are the end product of GL.\n\n**Answer:**\n\"I build the account hierarchies first, for natural account and cost center, because the report depends on them. Then I use Financial Reporting Studio, or Smart View or Narrative Reporting, against the GL balances cube. Rows are hierarchy nodes like Revenue, COGS and Opex; columns are periods and scenarios like Actual, Budget and Prior Year; and the point of view is ledger, company and currency. I add formulas for variances and percentages, formatting, and drill-down to journals. Then I publish to the Financial Reporting Center and schedule batches if needed. Before release, I reconcile it to the trial balance.\"\n\nTip: End with reconciling to the trial balance. It's the step that builds trust.", "D", null, null, {"f":["What's the first thing you'd validate in a new financial statement?","That totals tie to the trial balance for the same period and ledger."]}],
["Reporting", "When would you choose OTBI vs BI Publisher?", "**Why they ask:** picking the wrong tool wastes time.\n\n**Answer:**\n\"OTBI is self-service, drag and drop on subject areas, real-time, and it applies user security automatically. It's best for ad-hoc analysis, dashboards and simple lists, but it can't join everything and formatting is basic. BI Publisher uses SQL data models with RTF, Excel or eText templates for pixel-perfect output. It's best for documents like checks, invoices and statements, bank files, complex joins and extracts, and bursting. It needs more technical skill, and you have to handle data security in the SQL yourself. So I start with OTBI and move to BIP when formatting or data complexity requires it.\"\n\nTip: Mention that BIP doesn't apply data security on its own. It's a senior-level point.", "B", null, null, {"f":["Which would you use for an AP check template?","BI Publisher, because checks need pixel-perfect layouts."]}],
["Reporting", "What is a BIP data model and how do you secure a BIP report?", "**Why they ask:** BIP security is often done wrong.\n\n**Answer:**\n\"A data model defines the data: SQL queries, parameters, lists of values, links between data sets, and event triggers. The report applies a layout template, RTF, Excel or eText, to that data. To secure it, I put the report in a catalog folder with permissions for specific roles. And in the SQL, I filter the data by the user's access, for example by joining to the business unit security views, because BIP doesn't apply data security automatically.\"\n\nTip: The SQL security point is what separates senior from junior. Make sure you say it.", "D", null, null, {"f":["How do you secure a BIP report by business unit?","Use data security in the data model, joining to the user's granted BUs, or role-based access to the catalog folder."]}],
["Period Close", "How do you use the Close Monitor and close tasks in Fusion?", "**Why they ask:** close visibility is what controllers want.\n\n**Answer:**\n\"The Close Monitor shows period status across subledgers and ledgers in one view, so you can see which are open, closed or pending, and drill into each. Many companies use the task manager in EPM Financial Consolidation and Close, or a tool like BlackLine, for the close checklist, with owners, dependencies and due dates. I set the checklist up to follow the real close sequence, with evidence attached for audit.\"\n\nTip: Mention attaching evidence. Auditors ask for it every quarter.", "D", null, null, {"f":["How does the Close Monitor help the controller?","It shows which subledgers and ledgers are still open, so the controller sees close blockers quickly."]}],
["Period Close", "How do you handle period-end accruals for received but not invoiced (RNI) goods?", "**Why they ask:** RNI accruals are a common audit area.\n\n**Answer:**\n\"There are two methods. Accrue at receipt, common for inventory and many expense items, books the accrual when goods are received and clears it when the invoice is matched. Period-end accrual, used for some expense items, runs the accrual process at period end, and the entry reverses next period. Either way, I review the accrual reconciliation report for old or wrong accruals and write them off with approval. Finance decides which method applies by item and destination type.\"\n\nTip: Mention reviewing old accruals. Stale RNI balances are a classic audit finding.", "D", null, null, {"t":1,"f":["Which method would you use for services?","Period-end accrual is common for expense items without receipts, but if services are received in the system, accrue at receipt gives better accuracy."]}],
["Multi-currency", "How are exchange rates managed and used in Oracle?", "**Why they ask:** missing rates block accounting.\n\n**Answer:**\n\"There are rate types, like Corporate, Spot and User. Daily rates are loaded by hand, by spreadsheet, or through an integration from a provider like Reuters, Bloomberg or a bank. Transactions use the rate for their date and rate type, and User rate types let someone type a rate. Revaluation uses period-end rates, and translation uses period-end, average and historical rates. The key operational point is that rates must be loaded before processing, because a missing rate stops accounting.\"\n\nTip: End with the missing-rate point. It's the problem everyone has hit once.", "B", null, null, {"f":["What happens if a daily rate is missing?","Transactions using that rate type and date can't convert, and accounting fails until the rate is loaded."]}],
["Multi-currency", "How do realized gains and losses arise in AP and AR?", "**Why they ask:** a basic multi-currency accounting question.\n\n**Answer:**\n\"A realized gain or loss happens when a foreign-currency invoice is paid or receipted at a different rate than the invoice rate. For example, a EUR 1,000 supplier invoice booked at 1.10 is $1,100. If we pay it when the rate is 1.12, it costs $1,120, so that's a $20 realized loss. SLA books it to the realized gain or loss account at payment or receipt. Unrealized gains and losses are different: they come from revaluing open balances at period end.\"\n\nTip: Work the example out loud. It makes the answer stick.", "B", null, null, {"f":["What's the difference between realized and unrealized gains?","Realized happens at settlement; unrealized is from revaluation of open balances at period end."]}],
["Lease Accounting", "What do you know about Oracle Fusion Lease Accounting?", "**Why they ask:** a broad opening question about the lease module.\n\n**Answer:**\n\"It supports ASC 842 and IFRS 16 for lessees. You set up lease contracts with payments, terms and options. It calculates the right-of-use asset and the lease liability as the present value of the payments at the discount rate. Under ASC 842 it classifies each lease as finance or operating. It generates the amortization schedules, the journals, and the AP invoices for payments, and it links to Assets for ROU assets. It also handles modifications, impairments and terminations.\"\n\nTip: If you've done a lease project, add one number, like how many leases you onboarded.", "D", null, null, {"f":["What's the difference in expense pattern between ASC 842 operating and finance leases?","Operating leases have straight-line expense; finance leases have front-loaded expense from interest and amortization."]}],
["Expenses", "How do you configure expense policies and corporate cards?", "**Why they ask:** a detailed setup question for Expenses projects.\n\n**Answer:**\n\"I start with expense templates and expense types, like meals, hotel and mileage, each with a default account. Then the policies: rate limits by location or job level, daily limits, when receipts are required, and when a justification is needed. Each policy can be a warning or a hard error. Mileage rates are set by period and vehicle type. For corporate cards, I set up the card program, the issuer file load for Amex or Visa, matching to employees, and the payment option: company pay or individual pay. Finally the audit rules and receipt management.\"\n\n- **Templates and expense types** with default accounts.\n- **Policies:** rate and daily limits, receipt and justification rules, warning or error.\n- **Mileage rates.**\n- **Corporate cards:** program, issuer file, employee matching, company or individual pay.\n- **Audit rules** and receipt management.\n\nTip: Mention warning versus error and why you chose each. That's the design judgment they're looking for.", "D", null, null, {"f":["How do you stop duplicate card transactions on reports?","Card transactions import once and are matched to the report; policies flag duplicates."]}],
["Security", "How do you design custom roles for a finance implementation?", "**Why they ask:** role design affects audit and SoD.\n\n**Answer:**\n\"I start from the seeded job roles and map them to the client's real jobs: AP clerk, AP supervisor, GL accountant, controller. I copy the seeded roles and remove privileges that aren't needed, rather than building from scratch. I check segregation of duties conflicts, like supplier maintenance plus payments. I assign data access per BU or ledger. I document the design and get sign-off from the controller and audit. And I test each role with real scenarios, including negative tests to prove what a user can't do.\"\n\nTip: Mention negative tests. Proving what users can't do is half of security testing.", "D", null, null, {"t":1,"f":["How do you check segregation of duties in custom roles?","Run an SoD analysis, like Risk Management or a role matrix, checking conflicts like supplier creation plus payment."]}],
["Data Migration", "How do you convert open AP invoices and validate the conversion?", "**Why they ask:** conversion errors show up as wrong payments.\n\n**Answer:**\n\"I extract open invoices as of cutover and usually load only the remaining unpaid amount. They load through FBDI, Payables Standard Invoice Import, with supplier, site, terms, due dates and the original invoice number. I validate and account them, and the offset goes to a conversion clearing account that's cleared by the GL balance conversion. Then I reconcile count and amount by supplier against the legacy aging, and finance signs off. I do this in at least two mock conversions before production.\"\n\nTip: Mention keeping original invoice numbers and due dates. Payment timing depends on them.", "D", null, null, {"t":1,"f":["How do you prove the conversion is right?","Reconcile counts and totals by supplier and aging bucket to legacy, and to the GL liability at cutover."]}],
["EBS", "What is MOAC in EBS R12?", "**Why they ask:** EBS knowledge still matters for migrations.\n\n**Answer:**\n\"Multi-Org Access Control lets a user work with several operating units from one responsibility. It's controlled by a security profile, set in the MO: Security Profile option, listing the operating units, and MO: Default Operating Unit sets the default. Before R12, users needed a separate responsibility for each operating unit. In Fusion, the equivalent is data access by business unit through data roles.\"\n\nTip: Link it to Fusion. It shows you can help EBS clients move.", "D", null, null, {"f":["What's the Fusion equivalent of MOAC?","Data access by business unit assigned to roles in Manage Data Access for Users."]}],
["EBS", "What are the key differences between EBS and Fusion for Financials consultants?", "**Why they ask:** many clients are moving from EBS to Fusion.\n\n**Answer:**\n\"Operating units become business units. Responsibilities become job roles plus data access. Concurrent programs become scheduled processes. Forms and Discoverer give way to OTBI, BIP and Smart View. Custom code and CEMLIs give way to extensions only: Visual Builder, OIC and BIP. Patching by the customer becomes quarterly updates by Oracle. And there are new capabilities: AI agents, Smart View on live balances, embedded analytics, and Intelligent Document Recognition.\"\n\nTip: Show you can explain these to an EBS client. That's often the job.", "B", null, null, {"f":["What's the hardest habit for EBS users moving to Fusion?","Losing direct database access and custom code; they need to rely on configuration, extensions and reports."]}],
["Quarterly Updates", "How do you manage Oracle's quarterly updates?", "**Why they ask:** every Fusion customer lives with quarterly updates.\n\n**Answer:**\n\"I read the release readiness and What's New documents for our modules, and identify opt-in features worth enabling and mandatory changes. Updates reach test two weeks before production, so I run the regression pack, ideally automated, for key flows: P2P, O2C, close, payments, integrations and reports. Issues are logged and service requests raised early. And users get release notes and training.\"\n\nTip: Mention the two-week window. It shows you know the real timeline.", "B", null, null, {"f":["How do you regression test quarterly updates efficiently?","Keep a core set of test scripts for critical flows and run them each update, automated where possible."]}],
["Testing", "How do you write a good functional test script?", "**Why they ask:** good test scripts make UAT and regression work.\n\n**Answer:**\n\"It has a clear purpose, which requirement or scenario it tests. It lists preconditions and data: supplier, item and user role. The steps are written so a business user can follow them. Each step has an expected result, including accounting entries and reports. It includes negative cases, what should fail. It traces back to requirements, and evidence like screenshots is captured. And I reuse the scripts as the regression pack for quarterly updates.\"\n\nTip: Mention reuse for regression. It doubles the value of the work.", "B", null, null, {"f":["Why include negative tests?","To prove controls work, like a user who shouldn't approve being blocked."]}],
["Design", "What goes into a functional design document?", "**Why they ask:** design documents are a consultant's main deliverable.\n\n**Answer:**\n\"The business requirement and scope. Current and future process flows. Configuration decisions with the values and the reasons. Gaps and how they're solved, with extensions, reports or workarounds. Integration and data touchpoints. Security and controls. Assumptions, dependencies and open items. And sign-off. A good design document lets someone else configure the module without asking me.\"\n\nTip: End with \"someone else can configure from it\". That's the quality bar.", "B", null, null, {"f":["What makes a design document useful after go-live?","It records decisions and reasons, so support teams understand why things are set up that way."]}],
["Behavioral", "Tell me about a time you disagreed with your lead or the client on a design decision.", "**Why they ask:** they want to see you push back respectfully, with facts.\n\n**Answer (example):**\n\"My lead wanted one ledger for the US and Canada, with a CAD reporting currency. I owned the GL design and saw a problem: the Canadian entity needed a different fiscal calendar for statutory reporting. I prepared a short comparison of one ledger, separate ledgers, and a secondary ledger, showed that the calendar difference made a shared ledger impossible, and recommended a separate Canadian primary ledger. My lead agreed after the walkthrough, and we avoided rework later.\"\n\nTip: Show facts, respect and a recommendation, and say you'd accept the final decision either way.", "B", null, null, {"t":1,"f":["What did you learn from that disagreement?","Bring facts and options, not opinions; showing the reporting and audit impact usually settles design debates."]}],
["Behavioral", "How do you mentor junior consultants?", "**Why they ask:** senior roles include developing others.\n\n**Answer:**\n\"I pair them on real tasks: they configure, I review. I explain why, not just which screen, including the accounting behind each setup. I give them ownership of a small area, like payment terms or tax setup, with check-ins. I share checklists, sample test scripts, and how to search My Oracle Support. And I give feedback early and specifically.\"\n\nTip: Mention one person you helped and where they are now. It makes it real.", "B", null, null, {"f":["How do you know a junior consultant is ready for more?","When they can explain the accounting impact of a setup and handle a client question without me."]}],
["Behavioral", "How do you handle scope creep from finance users during a project?", "**Why they ask:** scope creep sinks go-live dates.\n\n**Answer:**\n\"I log every new request in the requirements or change log. I assess the impact on effort, timeline and risk. I separate what's needed for go-live from what can go to phase 2. I take it to the project manager and business owner for a decision, rather than silently absorbing it. And I tell the requester what was decided.\"\n\nTip: Show you protected the go-live date without dismissing the business.", "B", null, null, {"f":["How do you say no to a user without damaging the relationship?","Explain the impact, offer a timeline for later phases, and log it so they know it isn't forgotten."]}],
["General Ledger", "How do you design account hierarchies for reporting?", "**Why they ask:** hierarchies drive every GL report.\n\n**Answer:**\n\"I build trees for the natural account, assets, liabilities, equity, revenue and expense with sub-levels, and for cost centers, department to division to company. They follow the financial statement lines and management reporting. Tree versions are date-effective; I audit and flatten them, then publish to the Essbase cube. The same hierarchies are used in allocations, Financial Reporting and Smart View. And changes are governed: someone owns the tree, and changes go through change control.\"\n\nTip: Mention publishing to the cube. Forgetting it is why reports don't roll up.", "D", null, null, {"f":["Why build hierarchies before reports?","Reports roll up through hierarchies, so bad hierarchies mean every report is wrong."]}],
["General Ledger", "What is a ledger set and why use one?", "**Why they ask:** a basic question about managing many ledgers.\n\n**Answer:**\n\"A ledger set groups ledgers that share the same chart of accounts and calendar. With it I can open and close periods for many ledgers at once, run revaluation, translation, allocations and reports across them, and give access with one data access set. The ledgers can have different currencies. It's very useful for companies with many country ledgers.\"\n\nTip: Give a scale example, like closing 20 European ledgers in one step.", "B", null, null, {"f":["Can a ledger set include different currencies?","Yes, as long as the chart of accounts and calendar are the same."]}],
["Accounts Payable", "How do you prevent supplier bank account fraud in Oracle?", "**Why they ask:** fake bank change requests are one of the most common payment frauds. They want real controls.\n\n**Answer:**\n\"The first control is segregation of duties: the people who process invoices can't create or change supplier bank accounts. Supplier changes through the portal go through approval as supplier profile change requests. Before approving any bank change, someone calls the supplier on a contact number we already have on file, never the number in the request. I run a report of bank account changes before every payment run, and the first payment to a new account is held for review. Those four together stop most attempts.\"\n\n- **Segregation of duties** on bank account changes.\n- **Approval** of supplier profile change requests.\n- **Callback** to a known contact.\n- **Bank change report** before each payment run.\n- **Hold first payment** to a new account.\n\nTip: Mention a real control and the segregation-of-duties conflicts you checked. Concrete detail makes this answer believable.", "D", null, null, {"f":["What's the single most effective control?","Independent verification of bank changes by phone using a known contact, not details in the change request."]}],
["Accounts Payable", "What are the key Payables options and invoice options you configure?", "**Why they ask:** these settings drive behavior across the whole business unit, and getting them wrong is costly.\n\n**Answer:**\n\"Invoice options are where most of the decisions are: invoice approval, whether paid invoices can be adjusted, duplicate invoice checking, invoice currency, receipt acceptance days, the terms date basis and whether validation comes before approval. Matching options cover tolerances, whether distributions can be overridden and recalculation on match. Payment options cover things like allowing a payment date before the system date, who bears bank charges and payment document settings. The accounting options set accrual or cash basis, automatic offsets and the prepayment account. All of these are set per business unit, so I agree them with each BU's controller.\"\n\nTip: End with \"set per business unit, agreed with each controller.\" It shows you manage the decision, not just the screen.", "D", null, null, {"f":["Which option prevents duplicate payments?","Duplicate invoice checking by supplier, invoice number and amount, plus training users not to vary invoice numbers."]}],
["Accounts Receivable", "How do you set up AutoMatch for receipts?", "**Why they ask:** AutoMatch is how Fusion automates cash application. They want to see you can tune it.\n\n**Answer:**\n\"I create AutoMatch rule sets that tell Fusion how to match receipt remittance references to open transactions. The key settings are the thresholds: the customer recommendation threshold, the combined weighted threshold, and how many days of closed invoices to consider. Fusion scores each possible match using exact and partial string matching and weights them. Then application exception rules decide what to do with small differences, like writing off under $5 or putting overpayments on account. After go-live I watch the results for a few weeks and adjust the thresholds. Too strict and nothing applies; too loose and receipts go to the wrong invoices.\"\n\nTip: Explain the trade-off of strict vs loose thresholds. It shows you've tuned it, not only set it up.", "D", null, null, {"f":["What's the risk of setting AutoMatch thresholds too low?","Receipts apply to the wrong invoices, creating cleanup work."]}],
["Cash Management", "What is cash positioning and forecasting in Fusion?", "**Why they ask:** to see if you can talk to treasury.\n\n**Answer:**\n\"Cash positioning shows today's position by bank account and currency: the opening balance from the bank statement, plus expected inflows like AR receipts, minus outflows like AP payments and payroll. Cash forecasting projects that into future periods, using AP, AR, purchase orders, sales orders, payroll and outside sources. Treasury uses both to decide funding, investments and intercompany transfers. Many large companies also run a dedicated treasury system like Kyriba, with Fusion feeding it the data.\"\n\nTip: Say what treasury decides with it. That's what makes the answer useful.", "D", null, null, {"f":["Where does forecast data come from?","AP scheduled payments, AR expected receipts, payroll and manual entries."]}],
["Behavioral", "Describe a complex production issue you resolved during month-end.", "**Why they ask:** month-end issues test calm problem solving.\n\n**Answer (example):**\n\"On day two of close, Create Accounting for Payables failed for 800 invoices. I was the AP lead. The error showed an invalid account combination, and I traced it to a cost center the GL team had end-dated the day before. I enabled the old cost center temporarily, reran accounting, then worked with GL to reclass the balances and add a check to the cost center change process. Close finished on time, and we added a pre-close report that flags disabled accounts.\"\n\nTip: Root cause plus a process fix is what makes it a senior answer.", "B", null, null, {"f":["How did you find the root cause?","The error report showed an inactive account segment; fixing the value and rerunning Create Accounting cleared it."]}]
]);

// Added Oct 2026: more functional, Fusion platform, Redwood and AI Agent Studio questions.
QB["ora-sfc-fin"] = (QB["ora-sfc-fin"] || []).concat([
["Redwood", "How do you plan the move from classic to Redwood pages for a Finance module?", "**Why they ask:** a hands-on planning question.\n\n**Answer:**\n\"I list the pages users rely on, like AP invoices, journals, expenses and receipts, and which are Redwood in the current release. I find classic Page Composer personalizations, since they don't migrate, and decide which to rebuild in Visual Builder Studio. I enable Redwood in a test environment through profile options or opt-ins and run test scripts end to end, including reports and deep links in emails. Then short role-based training and job aids, and the switch module by module outside month-end while watching tickets. Classic pages are being retired, so it's better to plan than wait.\"\n\nTip: Mention testing deep links in approval emails. They often break.", "D", null, null, {"f":["What's the biggest risk in the Redwood move?","Lost personalizations and user confusion, which is why I test and train first."]}],
["Redwood", "How would you add a required field and a validation to a Redwood Payables page?", "**Why they ask:** a hands-on VBS question.\n\n**Answer:**\n\"If it's new data, I create a descriptive flexfield segment and deploy it. In Visual Builder Studio I open the Payables page extension in a workspace, add the field to the layout, make it required, and add a rule, for example required only when the invoice type is Standard and the amount is over $10,000. I preview, test in the test environment, then publish. And I update integrations and reports to include the new field.\"\n\nTip: Mention updating integrations. A new required field breaks FBDI loads otherwise.", "D", null, null, {"f":["How do you deploy that change?","Publish the Visual Builder extension from test to production after validation, following change control."]}],
["Redwood", "What happens to OTBI reports, BIP reports and integrations when pages move to Redwood?", "**Why they ask:** clients worry about breaking reports and integrations.\n\n**Answer:**\n\"REST and SOAP APIs, FBDI and the data model don't change, so integrations generally keep working. OTBI and BIP reports keep working too, though analytics embedded on pages may look or behave differently, so I test them. Deep links in approval emails or reports can change format, so I test notification links. And personalizations have to be rebuilt in Visual Builder Studio.\"\n\nTip: Start with the reassurance: APIs and data don't change.", "D", null, null, {"f":["What might break with Redwood?","Page Composer customizations and embedded analytics on classic pages."]}],
["AI Agent Studio", "Walk me through creating an AI agent in AI Agent Studio.", "**Why they ask:** a hands-on question for anyone claiming agent experience.\n\n**Answer:**\n\"I start from a delivered template, or the agent builder assistant where I describe what I want in plain words, or from scratch. I write clear instructions: role, goal, boundaries and tone. I add topics to scope what it handles. Then tools: for example a Business Object tool to read invoices and holds, a Document tool for policies, an Email tool, and a Deep Link tool to open the record in Fusion. I choose the LLM. I test in the studio with sample questions and review the trace of tool calls. Then I publish it and make it available to the right roles and pages.\"\n\nTip: Mention reviewing traces. It's how you know the agent used the right data.", "D", null, null, {"f":["How do you write good agent instructions?","Clear role, what it can and can't do, which tools to use, and how to answer."]}],
["AI Agent Studio", "What tool types can an agent use in AI Agent Studio?", "**Why they ask:** a technical knowledge question.\n\n**Answer:**\n\"Business Object tools read or act on Fusion objects through APIs, like invoices, suppliers, POs and journals. Document tools answer from uploaded documents using retrieval. External REST and connector tools call outside systems. MCP tools connect to tools exposed through the Model Context Protocol. Email tools send emails. Deep Link tools give the user a link straight to the Fusion page. User session tools use context about the signed-in user. I give each agent only the tools it needs.\"\n\nTip: End with \"only the tools it needs\". It's the security principle.", "D", null, null, {"f":["Which tool type would you use for policy questions?","Document tools, using the uploaded policy documents."]}],
["AI Agent Studio", "How would you test an agent before giving it to AP users?", "**Why they ask:** testing is what separates a demo from production.\n\n**Answer:**\n\"I build an evaluation set of 20 to 50 realistic questions with expected answers: holds, payment dates, policy questions, edge cases, and things it must refuse. I run it in the studio and review traces to see which tools were called and what came back. I check security by testing with users from different BUs. I check tone and accuracy and tighten the instructions. Then a pilot with a few users, watching the dashboard for sessions, errors, latency and token use.\"\n\nTip: Mention \"must refuse\" cases. They test the boundaries, not just the happy path.", "D", null, null, {"f":["What pass rate would you accept before rollout?","High accuracy on the evaluation set, and zero failures on things it must refuse."]}],
["AI Agent Studio", "Which Finance processes are good candidates for AI agents, and which are not?", "**Why they ask:** a judgment question.\n\n**Answer:**\n\"Good candidates are high-volume questions and lookups, like invoice and payment status, policy questions and expense help; exception triage, like explaining holds, suggesting fixes and drafting supplier or customer emails; document intake for invoices, remittances and receipts; and reconciliation help, suggesting matches with explanations. Poor candidates without strong controls are approving payments, posting journals and changing bank details, which keep human approval, and judgment-heavy accounting decisions.\"\n\nTip: Name bank detail changes as off-limits. It shows fraud awareness.", "D", null, null, {"f":["Which processes shouldn't use agents?","Ones needing judgment and accountability, like approving large payments or posting journals without review."]}],
["General Ledger", "How do you handle a journal posted to the wrong period?", "**Why they ask:** a common real-world mistake.\n\n**Answer:**\n\"If the wrong period is still open, I reverse the journal in that same period and re-enter it in the right one. If the wrong period is closed, I reverse it in the current open period, or reopen if policy allows, and post it correctly, with documentation for audit. Then I check whether allocations, revaluation or reports already used the wrong balance. And I fix the cause, often the default period on a spreadsheet upload, or a training gap.\"\n\nTip: Mention checking downstream effects like allocations. It shows thoroughness.", "B", null, null, {"f":["What if the wrong period is closed?","Reverse in the current open period and re-enter correctly, and document why."]}],
["Accounts Payable", "How do you set up and use payment terms with installments?", "**Why they ask:** staged payments are common for large purchases, and installments are often set up wrong.\n\n**Answer:**\n\"I define payment terms with more than one line, for example 50% due in 30 days and 50% in 60 days, each line with its own optional discount. When an invoice uses those terms, Oracle creates the installments automatically, each with its own due date and amount. The payment run picks up each installment when it's due. It's useful for large equipment purchases or contracts with staged payments.\"\n\n**Worked example:** $200,000 invoice dated June 1, terms 50/30, 50/60.\n- Installment 1: $100,000 due July 1.\n- Installment 2: $100,000 due July 31.\n\nTip: A quick numeric example makes a dry setup question easy to follow.", "D", null, null, {"f":["How does AP show installments?","As separate payment schedules on the invoice, each with its own due date."]}],
["Accounts Receivable", "How does an on-account credit memo differ from a regular credit memo?", "**Why they ask:** a basic question to check you know where credits sit.\n\n**Answer:**\n\"A regular credit memo is applied to a specific invoice and reduces that invoice's balance, for example crediting one damaged line. An on-account credit memo isn't tied to any invoice. It sits on the customer's account as a credit, like a goodwill credit or a rebate, and can be applied later to any invoice or refunded. Both reduce the customer's balance and create accounting through SLA. The thing to watch is that on-account credits don't sit for months; I'd include them in the weekly unapplied review.\"\n\nTip: Add the point about reviewing old on-account credits. It shows control thinking.", "B", null, null, {"f":["When would you use an on-account credit memo?","When the customer is due a credit not tied to one invoice, like a rebate."]}],
["Cash Management", "How do you handle bank charges and interest in reconciliation?", "**Why they ask:** a practical question about removing manual work.\n\n**Answer:**\n\"I use transaction creation rules. When a statement line matches a pattern, like the bank's fee code or 'INTEREST' in the description, Fusion creates an external cash transaction with the correct expense or income account, and autoreconciliation then clears it. Before close, someone reviews what was created, because a bank can change a code and a rule can start catching the wrong lines.\"\n\nTip: Add the review step. It shows you think about controls even on automation.", "D", null, null, {"f":["What accounting does a transaction creation rule create?","An external cash transaction, for example debit bank charges and credit cash."]}],
["Expenses", "How do you handle an employee who submitted an expense report with a policy violation?", "**Why they ask:** a practical question that shows how you'd balance policy and employee experience.\n\n**Answer:**\n\"The system flags it first: policy rules mark the line as a warning or an error. A warning lets the employee submit with a justification. An error blocks submission until it's fixed. The manager sees any violations during approval, and auditors can reject or adjust lines. If it's a pattern, I don't just keep rejecting reports. I report violations by department, and either the policy gets clearer, the employee gets training, or the rule gets tighter.\"\n\nTip: Talk about patterns, not just the one report. Interviewers want to hear you'd fix the root cause.", "B", null, null, {"f":["What do you do if the same employee keeps violating policy?","Report patterns to their manager and HR, and tighten approval for that employee if needed."]}]
]);
